test("facturasVigentes: devuelve solo las emitidas sin modificar la lista", () => {
  const a = emitirFactura({ numero: 1, nit: "1023456", razonSocial: "A", items: [{ cantidad: 1, precioUnitarioCentavos: 100 }] });
  const b = { ...a, numero: 2, estado: "anulada" };
  const c = emitirFactura({ numero: 3, nit: "1023456", razonSocial: "C", items: [{ cantidad: 1, precioUnitarioCentavos: 200 }] });
  const lista = Object.freeze([a, b, c]);
  const vigentes = facturasVigentes(lista);
  assert.deepEqual(vigentes.map((f) => f.numero), [1, 3]);
  assert.notEqual(vigentes, lista);
  assert.equal(lista.length, 3);
  assert.deepEqual(facturasVigentes([]), []);
  assert.throws(() => facturasVigentes(null), TypeError);
});
