const ajuste = (cantidadContada, motivo = "  recuento físico mensual  ") =>
  ({ articulo: "A1", almacen: "LPZ", cantidadContada, motivo });

test("ajuste: si sobra stock agrega un ingreso por la diferencia, con motivo recortado", () => {
  const antes = conIngreso();
  const despues = ajustarInventario(antes, ajuste(14));
  assert.equal(antes.length, 1);
  assert.equal(despues.length, 2);
  assert.equal(stock(despues, "A1", "LPZ"), 14);
  assert.deepEqual(despues[1], { tipo: "ingreso", articulo: "A1", almacen: "LPZ", cantidad: 4, motivo: "recuento físico mensual" });
});

test("ajuste: si falta stock agrega un egreso; contar 0 vacía el almacén", () => {
  assert.equal(stock(ajustarInventario(conIngreso(), ajuste(6)), "A1", "LPZ"), 6);
  assert.equal(stock(ajustarInventario(conIngreso(), ajuste(0)), "A1", "LPZ"), 0);
});

test("ajuste: si el recuento coincide no agrega nada", () => {
  const antes = conIngreso();
  assert.equal(ajustarInventario(antes, ajuste(10)), antes);
});

test("ajuste: rechaza cantidad inválida y motivo corto o no textual (L-motivo-minimo-auditoria)", () => {
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(-1)), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(1.5)), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(5, "  corto   ")), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(5, 12345678901)), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), ajuste(5, undefined)), RangeError);
});
