const AJUSTE = { id: "S-1", fecha: "2026-11-01", sku: "CAFE-250", delta: 10, motivo: "compra" };

test("RF-005: venta.registrada admite canal tienda o web, solo si viene", () => {
  assert.equal(crearVentaRegistrada({ ...VENTA, canal: "web" }).canal, "web");
  assert.equal(crearVentaRegistrada({ ...VENTA, canal: "tienda" }).canal, "tienda");
  assert.equal("canal" in crearVentaRegistrada(VENTA), false);
  assert.equal("canal" in crearVentaRegistrada({ ...VENTA, canal: undefined }), false);
  for (const malo of ["otro", "", "Web", 1])
    assert.throws(() => crearVentaRegistrada({ ...VENTA, canal: malo }), RangeError);
});

test("RF-006: stock.ajustado admite almacen ALM-dd, solo si viene", () => {
  assert.equal(crearStockAjustado({ ...AJUSTE, almacen: "ALM-02" }).almacen, "ALM-02");
  assert.equal("almacen" in crearStockAjustado(AJUSTE), false);
  for (const malo of ["ALM-1", "alm-01", "ALM-001", "ALM-01 ", "", 1])
    assert.throws(() => crearStockAjustado({ ...AJUSTE, almacen: malo }), RangeError);
});

test("RF-001: los campos nuevos no se cuelan en el otro tipo de evento (estricto)", () => {
  assert.throws(() => crearStockAjustado({ ...AJUSTE, canal: "web" }), TypeError);
  assert.throws(() => crearVentaRegistrada({ ...VENTA, almacen: "ALM-01" }), TypeError);
  assert.throws(() => crearVentaRegistrada({ ...VENTA, canal: "web", color: "rojo" }), TypeError);
});

test("RF-001: los eventos válidos antes del cambio siguen siendo válidos", () => {
  assert.doesNotThrow(() => validarEvento({ tipo: "venta.registrada", ...VENTA }));
  assert.doesNotThrow(() => validarEvento({ tipo: "stock.ajustado", ...AJUSTE }));
});
