  const eventos = [
    ajustarStock({ id: "S-1", fecha: "2026-11-01", sku: "cafe-250", delta: 20, motivo: "compra" }),
    ajustarStock({ id: "S-2", fecha: "2026-11-01", sku: "cafe-250", delta: 7, motivo: "compra", almacen: "ALM-02" }),
