const ventaCanal = (id, canal, cantidad, precio) => crearVentaRegistrada({ id, fecha: "2026-11-01", sku: "CAFE-250", cantidad, precioUnitarioCentavos: precio, canal });

test("RF-007-a: separa unidades y total por canal", () => {
  const eventos = [ventaCanal("V-1", "tienda", 2, 4500), ventaCanal("V-2", "web", 3, 1000), ventaCanal("V-3", "web", 1, 500)];
  assert.deepEqual(ventasPorCanal(eventos), {
    tienda: { unidades: 2, totalCentavos: 9000 },
    web: { unidades: 4, totalCentavos: 3500 },
  });
});

test("RF-007-b: una venta sin canal cuenta como tienda", () => {
  assert.deepEqual(ventasPorCanal(EVENTOS), {
    tienda: { unidades: 8, totalCentavos: 19500 },
    web: { unidades: 0, totalCentavos: 0 },
  });
});

test("RF-007-c: ignora los eventos que no son ventas", () => {
  const stock = crearStockAjustado({ id: "S-9", fecha: "2026-11-01", sku: "CAFE-250", delta: 5, motivo: "compra" });
  assert.deepEqual(ventasPorCanal([stock, ventaCanal("V-1", "web", 1, 100)]), {
    tienda: { unidades: 0, totalCentavos: 0 },
    web: { unidades: 1, totalCentavos: 100 },
  });
});

test("RF-007-d: sin ventas devuelve ambos canales en cero", () => {
  assert.deepEqual(ventasPorCanal([]), {
    tienda: { unidades: 0, totalCentavos: 0 },
    web: { unidades: 0, totalCentavos: 0 },
  });
});

test("RF-007-e: un evento inválido hace fallar el reporte (contrato estricto)", () => {
  const base = { tipo: "venta.registrada", id: "V-1", fecha: "2026-11-01", sku: "X", cantidad: 1, precioUnitarioCentavos: 100 };
  assert.throws(() => ventasPorCanal([{ ...base, canal: "mayorista" }]), RangeError);
  assert.throws(() => ventasPorCanal([{ ...base, extra: 1 }]), TypeError);
});
